<?php
$c=new mysqli(getenv("DB_HOST")?:"localhost",getenv("DB_USER")?:"root",getenv("DB_PASS")?:"");if($c->connect_error)die("Database connection failed.");$db=getenv("DB_NAME")?:"warehouse_employee";$c->query("CREATE DATABASE IF NOT EXISTS `$db` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");$c->select_db($db);$c->query("CREATE TABLE IF NOT EXISTS employees(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,employee_code VARCHAR(30) UNIQUE,name VARCHAR(100),department VARCHAR(80),shift_name VARCHAR(30),phone VARCHAR(20),status VARCHAR(30) DEFAULT 'Active',joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");
$msg="";if($_SERVER["REQUEST_METHOD"]==="POST"){$code=trim($_POST["code"]??"");$name=trim($_POST["name"]??"");$dep=trim($_POST["department"]??"");$shift=trim($_POST["shift"]??"");$phone=trim($_POST["phone"]??"");if($code&&$name&&$dep&&$shift){$s=$c->prepare("INSERT INTO employees(employee_code,name,department,shift_name,phone) VALUES(?,?,?,?,?)");$s->bind_param("sssss",$code,$name,$dep,$shift,$phone);$msg=$s->execute()?"Employee added successfully.":"Employee code already exists."; $s->close();}}
$rows=$c->query("SELECT * FROM employees ORDER BY id DESC LIMIT 100");function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,"UTF-8");}
?><!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Warehouse Employee System</title><style>body{font-family:Arial;background:#f8fafc;margin:0}.head{background:#b45309;color:#fff;padding:23px 7%;font-size:25px;font-weight:bold}.wrap{max-width:1100px;margin:35px auto;padding:20px}.card{background:white;padding:28px;border-radius:15px;box-shadow:0 5px 25px #0001;margin-bottom:25px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:15px}label{font-weight:bold}input,select{width:100%;padding:12px;margin-top:7px;box-sizing:border-box;border:1px solid #ccc;border-radius:7px}button{background:#b45309;color:white;border:0;padding:13px 20px;border-radius:7px;margin-top:18px;font-weight:bold}.msg{padding:12px;background:#dcfce7;color:#166534;border-radius:7px}.table{overflow:auto}table{width:100%;border-collapse:collapse;min-width:850px}th,td{padding:11px;border-bottom:1px solid #ddd;text-align:left}th{background:#b45309;color:white}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style></head><body><div class="head">📦 Warehouse Employee System</div><div class="wrap"><div class="card"><h2>Add Employee</h2><?php if($msg):?><div class="msg"><?=e($msg)?></div><?php endif;?><form method="post"><div class="grid"><div><label>Employee Code</label><input name="code" required></div><div><label>Name</label><input name="name" required></div><div><label>Department</label><select name="department" required><option value="">Select</option><option>Inventory</option><option>Dispatch</option><option>Receiving</option><option>Quality</option><option>Administration</option></select></div><div><label>Shift</label><select name="shift" required><option value="">Select</option><option>Morning</option><option>Afternoon</option><option>Night</option></select></div><div><label>Phone</label><input name="phone"></div></div><button>Add Employee</button></form></div><div class="card"><h2>Employee Records</h2><div class="table"><table><tr><th>ID</th><th>Code</th><th>Name</th><th>Department</th><th>Shift</th><th>Phone</th><th>Status</th><th>Joined</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r["id"])?></td><td><?=e($r["employee_code"])?></td><td><?=e($r["name"])?></td><td><?=e($r["department"])?></td><td><?=e($r["shift_name"])?></td><td><?=e($r["phone"])?></td><td><?=e($r["status"])?></td><td><?=e($r["joined_at"])?></td></tr><?php endwhile;?></table></div></div></div></body></html><?php $c->close();?>